#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MOD 998244353
#define MAXN 100005

typedef long long ll;

int n, m;
int head[MAXN], to[2*MAXN], nxt[2*MAXN], ecnt;
int color[MAXN];
int cnt[2];
int ok;

void add_edge(int u, int v) {
    to[ecnt] = v;
    nxt[ecnt] = head[u];
    head[u] = ecnt++;
}

void dfs(int u, int c) {
    if (color[u] != -1) {
        if (color[u] != c) ok = 0;
        return;
    }
    color[u] = c;
    cnt[c]++;
    for (int e = head[u]; e != -1; e = nxt[e]) {
        dfs(to[e], c ^ 1);
    }
}

ll solve_graph() {
    memset(head, -1, sizeof(head));
    memset(color, -1, sizeof(color));
    ecnt = 0;
    scanf("%d %d", &n, &m);
    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        u--; v--;
        add_edge(u, v);
        add_edge(v, u);
    }
    ll res = 1;
    for (int i = 0; i < n; i++) {
        if (color[i] == -1) {
            cnt[0] = cnt[1] = 0;
            ok = 1;
            dfs(i, 0);
            if (!ok) {
                // not bipartite -> maximum independent set is size of component
                res = (res * (cnt[0] + cnt[1])) % MOD;
            } else {
                int maxc = (cnt[0] > cnt[1]) ? cnt[0] : cnt[1];
                res = (res * maxc) % MOD;
            }
        }
    }
    return res;
}

