#include <stdio.h>
#include <stdlib.h>

#define MOD 998244353LL

long long solve(int n, int adj[], long long *result) {
    long long best = 0;
    for (int mask = 0; mask < (1 << n); mask++) {
        // check independent set
        int ok = 1;
        for (int i = 0; i < n && ok; i++) {
            if (!(mask & (1 << i))) continue;
            if (adj[i] & mask) { ok = 0; }
        }
        if (ok) {
            long long w = 0;
            for (int i = 0; i < n; i++) {
                if (mask & (1 << i)) w += (i + 1);
            }
            if (w > best) best = w;
        }
    }
    *result = best;
    return best;
}

