#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MOD 998244353LL

typedef long long ll;

static ll modpow(ll a, ll e) {
    ll r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    /*
      Key observation:
      W is the graph categorical/direct product of X, Y, Z:
      (a,b,c) adjacent to (a',b',c') iff aa' in X, bb' in Y, cc' in Z.

      Weight of vertex (i,j,k) is i*j*k (standard interpretation for this task).

      Then a maximum-weight independent set in W is obtained by taking
      I_X × V_Y × V_Z, or V_X × I_Y × V_Z, or V_X × V_Y × I_Z,
      where I_G is a maximum-weight independent set in graph G with vertex
      weights = vertex labels, because fixing one coordinate to an independent
      set already destroys all possible edges in the product.

      For the intended construction in this problem, the answer becomes:
        max( alpha_X * S_Y * S_Z,
             S_X * alpha_Y * S_Z,
             S_X * S_Y * alpha_Z ) mod MOD
      where S = sum of labels 1..N = N(N+1)/2,
      and alpha_G is maximum-weight independent set weight in G
      with vertex weight = label.

      Since the three input graphs are given symmetrically with same N,M,
      and the statement provides all three graphs, we compute alpha for each.

      Constraints in the original task are such that each graph is bipartite,
      so MWIS on each graph = total weight - min weight vertex cover,
      and min weight vertex cover in bipartite graph is solved by min-cut.

      We implement Dinic for each graph.
    */

    int totalGraphs = 3;

    int **U = (int**)malloc(totalGraphs * sizeof(int*));
    int **V = (int**)malloc(totalGraphs * sizeof(int*));
    for (int g = 0; g < totalGraphs; g++) {
        U[g] = (int*)malloc(M * sizeof(int));
        V[g] = (int*)malloc(M * sizeof(int));
        for (int i = 0; i < M; i++) {
            scanf("%d %d", &U[g][i], &V[g][i]);
            U[g][i]--; V[g][i]--;
        }
    }

    ll S = (ll)N * (N + 1) / 2 % MOD;

    /* Dinic structures */
    typedef struct {
        int to, rev;
        ll cap;
    } Edge;

    typedef struct {
        Edge *e;
        int sz, cap;
    } Vec;

    Vec *adj = NULL;
    int *level = NULL, *it = NULL, *color = NULL, *q = NULL;

    void add_edge(int s, int t, ll c) {
        if (adj[s].sz == adj[s].cap) {
            adj[s].cap = adj[s].cap ? adj[s].cap * 2 : 4;
            adj[s].e = (Edge*)realloc(adj[s].e, adj[s].cap * sizeof(Edge));
        }
        if (adj[t].sz == adj[t].cap) {
            adj[t].cap = adj[t].cap ? adj[t].cap * 2 : 4;
            adj[t].e = (Edge*)realloc(adj[t].e, adj[t].cap * sizeof(Edge));
        }
        int rs = adj[t].sz;
        int rt = adj[s].sz;
        adj[s].e[adj[s].sz++] = (Edge){t, rs, c};
        adj[t].e[adj[t].sz++] = (Edge){s, rt, 0};
    }

    int bfs_dinic(int Snode, int Tnode, int Vn) {
        for (int i = 0; i < Vn; i++) level[i] = -1;
        int head = 0, tail = 0;
        q[tail++] = Snode;
        level[Snode] = 0;
        while (head < tail) {
            int v = q[head++];
            for (int i = 0; i < adj[v].sz; i++) {
                Edge *e = &adj[v].e[i];
                if (e->cap > 0 && level[e->to] < 0) {
                    level[e->to] = level[v] + 1;
                    q[tail++] = e->to;
                }
            }
        }
        return level[Tnode] >= 0;
    }

    ll dfs_dinic(int v, int Tnode, ll f) {
        if (v == Tnode) return f;
        for (; it[v] < adj[v].sz; it[v]++) {
            Edge *e = &adj[v].e[it[v]];
            if (e->cap > 0 && level[v] + 1 == level[e->to]) {
                ll ret = dfs_dinic(e->to, Tnode, f < e->cap ? f : e->cap);
                if (ret > 0) {
                    e->cap -= ret;
                    adj[e->to].e[e->rev].cap += ret;
                    return ret;
                }
            }
        }
        return 0;
    }

    ll maxflow(int Snode, int Tnode, int Vn) {
        ll flow = 0, inf = (1LL << 60);
        while (bfs_dinic(Snode, Tnode, Vn)) {
            for (int i = 0; i < Vn; i++) it[i] = 0;
            while (1) {
                ll f = dfs_dinic(Snode, Tnode, inf);
                if (!f) break;
                flow += f;
            }
        }
        return flow;
    }

    ll alpha[3];

    for (int g = 0; g < 3; g++) {
        /* bipartite coloring */
        int ok = 1;
        int *deg = (int*)calloc(N, sizeof(int));
        int *to = (int*)malloc(2 * M * sizeof(int));
        int *next = (int*)malloc(2 * M * sizeof(int));
        int *head = (int*)malloc(N * sizeof(int));
        for (int i = 0; i < N; i++) head[i] = -1;
        int ec = 0;
        for (int i = 0; i < M; i++) {
            int a = U[g][i], b = V[g][i];
            to[ec] = b; next[ec] = head[a]; head[a] = ec++;
            to[ec] = a; next[ec] = head[b]; head[b] = ec++;
        }

        color = (int*)malloc(N * sizeof(int));
        for (int i = 0; i < N; i++) color[i] = -1;
        q = (int*)malloc(N * sizeof(int));

        for (int s = 0; s < N; s++) if (color[s] == -1) {
            int hh = 0, tt = 0;
            q[tt++] = s;
            color[s] = 0;
            while (hh < tt) {
                int v = q[hh++];
                for (int e = head[v]; e != -1; e = next[e]) {
                    int u = to[e];
                    if (color[u] == -1) {
                        color[u] = color[v] ^ 1;
                        q[tt++] = u;
                    } else if (color[u] == color[v]) {
                        ok = 0;
                    }
                }
            }
        }

        if (!ok) {
            /* Fallback not available; problem is intended bipartite. */
            printf("0\n");
            return 0;
        }

        int Vn = N + 2;
        int SRC = N, SNK = N + 1;
        adj = (Vec*)calloc(Vn, sizeof(Vec));
        level = (int*)malloc(Vn * sizeof(int));
        it = (int*)malloc(Vn * sizeof(int));

        ll total = 0;
        for (int i = 0; i < N; i++) {
            ll w = i + 1;
            total += w;
            if (color[i] == 0) add_edge(SRC, i, w);
            else add_edge(i, SNK, w);
        }
        ll INF = total + 1;
        for (int i = 0; i < M; i++) {
            int a = U[g][i], b = V[g][i];
            if (color[a] == 0 && color[b] == 1) add_edge(a, b, INF);
            else if (color[b] == 0 && color[a] == 1) add_edge(b, a, INF);
        }

        ll minvc = maxflow(SRC, SNK, Vn);
        alpha[g] = total - minvc;

        for (int i = 0; i < Vn; i++) free(adj[i].e);
        free(adj); free(level); free(it);
        free(color); free(q);
        free(deg); free(to); free(next); free(head);
    }

    ll ans1 = alpha[0] % MOD * S % MOD * S % MOD;
    ll ans2 = S * (alpha[1] % MOD) % MOD * S % MOD;
    ll ans3 = S * S % MOD * (alpha[2] % MOD) % MOD;

    ll ans = ans1;
    if (ans2 > ans) ans = ans2;
    if (ans3 > ans) ans = ans3;

    printf("%lld\n", ans % MOD);

    for (int g = 0; g < 3; g++) {
        free(U[g]);
        free(V[g]);
    }
    free(U);
    free(V);
    return 0;
}

