public class Main {
    static final int MOD = 998244353;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int Mx = sc.nextInt();
        int My = sc.nextInt();
        int Mz = sc.nextInt();

        long[] wX = new long[N];
        long[] wY = new long[N];
        long[] wZ = new long[N];
        for (int i = 0; i < N; i++) wX[i] = sc.nextLong();
        for (int i = 0; i < N; i++) wY[i] = sc.nextLong();
        for (int i = 0; i < N; i++) wZ[i] = sc.nextLong();

        boolean[][] gX = new boolean[N][N];
        boolean[][] gY = new boolean[N][N];
        boolean[][] gZ = new boolean[N][N];

        for (int i = 0; i < Mx; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            gX[u][v] = gX[v][u] = true;
        }
        for (int i = 0; i < My; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            gY[u][v] = gY[v][u] = true;
        }
        for (int i = 0; i < Mz; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            gZ[u][v] = gZ[v][u] = true;
        }

        long mwisX = maxWeightIndependentSet(N, wX, gX);
        long mwisY = maxWeightIndependentSet(N, wY, gY);
        long mwisZ = maxWeightIndependentSet(N, wZ, gZ);

        long ans = ((mwisX % MOD) * (mwisY % MOD) % MOD) * (mwisZ % MOD) % MOD;
        System.out.println(ans);
    }

    static long maxWeightIndependentSet(int n, long[] w, boolean[][] g) {
        int half = n / 2;
        int leftSize = half;
        int rightSize = n - half;

        // Precompute for all subsets of left half
        int leftMaskCount = 1 << leftSize;
        long[] bestLeft = new long[leftMaskCount];
        boolean[] validLeft = new boolean[leftMaskCount];

        for (int mask = 0; mask < leftMaskCount; mask++) {
            boolean ok = true;
            long sum = 0;
            for (int i = 0; i < leftSize && ok; i++) {
                if ((mask & (1 << i)) == 0) continue;
                sum += w[i];
                for (int j = i + 1; j < leftSize; j++) {
                    if ((mask & (1 << j)) != 0 && g[i][j]) {
                        ok = false;
                        break;
                    }
                }
            }
            validLeft[mask] = ok;
            bestLeft[mask] = ok ? sum : -1;
        }

        // For right half, precompute best for each mask and also compatibility with left
        int rightMaskCount = 1 << rightSize;
        long[] bestRight = new long[rightMaskCount];
        boolean[] validRight = new boolean[rightMaskCount];

        for (int mask = 0; mask < rightMaskCount; mask++) {
            boolean ok = true;
            long sum = 0;
            for (int i = 0; i < rightSize && ok; i++) {
                if ((mask & (1 << i)) == 0) continue;
                sum += w[leftSize + i];
                for (int j = i + 1; j < rightSize; j++) {
                    if ((mask & (1 << j)) != 0 && g[leftSize + i][leftSize + j]) {
                        ok = false;
                        break;
                    }
                }
            }
            validRight[mask] = ok;
            bestRight[mask] = ok ? sum : -1;
        }

        // For each left mask, precompute which right vertices are forbidden
        int[] forbiddenRightMask = new int[leftMaskCount];
        for (int leftMask = 0; leftMask < leftMaskCount; leftMask++) {
            int forb = 0;
            for (int i = 0; i < leftSize; i++) {
                if ((leftMask & (1 << i)) == 0) continue;
                for (int j = 0; j < rightSize; j++) {
                    if (g[i][leftSize + j]) {
                        forb |= (1 << j);
                    }
                }
            }
            forbiddenRightMask[leftMask] = forb;
        }

        // For each right mask, store best value for subsets
        long[] maxForRightMask = new long[rightMaskCount];
        for (int mask = 0; mask < rightMaskCount; mask++) {
            long maxVal = 0;
            int sub = mask;
            while (true) {
                if (validRight[sub]) {
                    maxVal = Math.max(maxVal, bestRight[sub]);
                }
                if (sub == 0) break;
                sub = (sub - 1) & mask;
            }
            maxForRightMask[mask] = maxVal;
        }

        long answer = 0;
        for (int leftMask = 0; leftMask < leftMaskCount; leftMask++) {
            if (!validLeft[leftMask]) continue;
            long leftWeight = bestLeft[leftMask];
            int allowedRightMask = ((1 << rightSize) - 1) ^ forbiddenRightMask[leftMask];
            long rightWeight = maxForRightMask[allowedRightMask];
            answer = Math.max(answer, leftWeight + rightWeight);
        }

        return answer;
    }
}

