#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
const int MOD = 998244353;

int maxWeightIndependentSet(const vector<vector<int>>& adj, const vector<int>& weight) {
    int n = weight.size();
    if (n == 0) return 0;
    int half = n / 2;
    int left = half, right = n - half;
    // Precompute for each mask on left side if it's independent
    vector<int> leftIndep(1 << left, 0);
    vector<int> leftWeight(1 << left, 0);
    for (int mask = 0; mask < (1 << left); ++mask) {
        bool ok = true;
        int w = 0;
        for (int i = 0; i < left && ok; ++i) if (mask & (1 << i)) {
            w += weight[i];
            for (int j = i+1; j < left; ++j) if (mask & (1 << j)) {
                if (adj[i][j]) { ok = false; break; }
            }
        }
        if (ok) {
            leftIndep[mask] = 1;
            leftWeight[mask] = w;
        }
    }
    // Precompute for right side best weight compatible with a given conflict mask
    vector<int> rightConf(1 << right, 0);
    for (int mask = 0; mask < (1 << right); ++mask) {
        bool ok = true;
        int w = 0;
        for (int i = 0; i < right && ok; ++i) if (mask & (1 << i)) {
            w += weight[left + i];
            for (int j = i+1; j < right; ++j) if (mask & (1 << j)) {
                if (adj[left + i][left + j]) { ok = false; break; }
            }
        }
        if (ok) rightConf[mask] = w;
        else rightConf[mask] = -1;
    }
    // For each right mask, store max weight for subsets that are supersets of it? Actually we need conflict mask: for each left mask, which right vertices conflict.
    vector<int> bestForConflict(1 << right, -1);
    for (int mask = 0; mask < (1 << right); ++mask) {
        if (rightConf[mask] < 0) continue;
        int conflict = 0;
        // conflict mask: bits set if any right vertex in mask conflicts with some left vertex? We'll handle differently.
        // Instead: precompute for each left mask the set of right vertices that conflict.
        // Then iterate over right submask that avoid those.
    }
    // Simpler: iterate over left masks, compute conflict mask for right, then iterate submask of complement.
    vector<int> rightMaskWeight(1 << right, -1);
    for (int m = 0; m < (1 << right); ++m) {
        if (rightConf[m] >= 0) rightMaskWeight[m] = rightConf[m];
    }
    // For superset max
    for (int i = 0; i < right; ++i) {
        for (int mask = 0; mask < (1 << right); ++mask) if (mask & (1 << i)) {
            if (rightMaskWeight[mask ^ (1 << i)] > rightMaskWeight[mask])
                rightMaskWeight[mask] = rightMaskWeight[mask ^ (1 << i)];
        }
    }
    int ans = 0;
    for (int lmask = 0; lmask < (1 << left); ++lmask) {
        if (!leftIndep[lmask]) continue;
        int conflict = 0;
        for (int i = 0; i < left; ++i) if (lmask & (1 << i)) {
            for (int j = 0; j < right; ++j) {
                if (adj[i][left + j]) conflict |= (1 << j);
            }
        }
        int allowed = ((1 << right) - 1) ^ conflict;
        int bestRight = rightMaskWeight[allowed];
        if (bestRight >= 0)
            ans = max(ans, leftWeight[lmask] + bestRight);
    }
    return ans;
}

