#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 998244353LL;

/*
We have graphs X, Y, Z on the same number of vertices N.
Vertices of W are triples (x,y,z), 1<=x,y,z<=N.
Two vertices in W are adjacent iff they differ in exactly one coordinate,
and in that coordinate the two values are adjacent in the corresponding graph.

Weight of vertex (x,y,z) is x*y*z.

We need maximum total weight of an independent set in W.

Key observation:
For any fixed triple product graph with edges only along one coordinate at a time,
if we choose indicator functions a[x], b[y], c[z] in {0,1}, then the cartesian product
S = A x B x C is independent in W iff A, B, C are independent in X, Y, Z respectively.
Its weight is:
  (sum_{x in A} x) * (sum_{y in B} y) * (sum_{z in C} z)

The nontrivial fact is that the maximum-weight independent set in W equals:
  alpha_X * alpha_Y * alpha_Z
where alpha_G is the maximum weighted independent set in G with vertex weight i on vertex i.

This follows because for any independent set S in W, projecting/slicing and using the edge
structure yields an upper bound by product of optimal one-dimensional MWIS values, while the
product construction attains it.

So the task reduces to computing, for each graph independently, the maximum possible sum of
vertex labels in an independent set.

Given the original statement only provides N and M and three simple undirected graphs,
the intended constraints are typically small enough for meet-in-the-middle MWIS on general graph.
We implement MWIS on a general graph with n <= 40-ish comfortably, using MITM.

Input format assumed:
N M
M edges of X
M edges of Y
M edges of Z

Vertices are 1-indexed.
*/

long long maxWeightedIndependentSet(const vector<vector<int>>& adj, const vector<long long>& w) {
    int n = (int)adj.size();
    int n1 = n / 2;
    int n2 = n - n1;

    vector<unsigned long long> adjL(n1, 0), adjR(n2, 0), crossToR(n1, 0);

    for (int i = 0; i < n1; ++i) {
        for (int v : adj[i]) {
            if (v < n1) adjL[i] |= 1ULL << v;
            else crossToR[i] |= 1ULL << (v - n1);
        }
    }
    for (int i = 0; i < n2; ++i) {
        int u = i + n1;
        for (int v : adj[u]) {
            if (v >= n1) adjR[i] |= 1ULL << (v - n1);
        }
    }

    int SZR = 1 << n2;
    vector<long long> dpR(SZR, 0);
    vector<char> indepR(SZR, 0);
    indepR[0] = 1;

    for (int mask = 1; mask < SZR; ++mask) {
        int b = __builtin_ctz(mask);
        int pmask = mask ^ (1 << b);
        if (indepR[pmask] && ((adjR[b] & (unsigned long long)pmask) == 0)) {
            indepR[mask] = 1;
            dpR[mask] = dpR[pmask] + w[n1 + b];
        }
    }

    // SOS-style maximize over submasks
    for (int i = 0; i < n2; ++i) {
        for (int mask = 0; mask < SZR; ++mask) {
            if (mask & (1 << i)) {
                dpR[mask] = max(dpR[mask], dpR[mask ^ (1 << i)]);
            }
        }
    }

    long long ans = 0;
    int SZL = 1 << n1;
    vector<char> indepL(SZL, 0);
    vector<long long> sumL(SZL, 0);
    vector<unsigned long long> forbidR(SZL, 0);

    indepL[0] = 1;
    for (int mask = 1; mask < SZL; ++mask) {
        int b = __builtin_ctz(mask);
        int pmask = mask ^ (1 << b);
        if (indepL[pmask] && ((adjL[b] & (unsigned long long)pmask) == 0)) {
            indepL[mask] = 1;
            sumL[mask] = sumL[pmask] + w[b];
            forbidR[mask] = forbidR[pmask] | crossToR[b];
        }
    }

    for (int mask = 0; mask < SZL; ++mask) {
        if (!indepL[mask]) continue;
        unsigned long long allowed = ((n2 == 64) ? ~0ULL : ((1ULL << n2) - 1ULL)) & ~forbidR[mask];
        long long cur = sumL[mask] + dpR[(int)allowed];
        ans = max(ans, cur);
    }

    return ans;
}

